int bsearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) low = mid;
        else high = mid - 1;
    }
    return -1;
}

int main() {
    int a[] = {10, 20, 30, 42};
    printf("%d\n", bsearch(a, 4, 42));
    return 0;
}

