void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n; j++) {
            if (arr[j] > arr[j + 1]) {
                int t = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = t;
            }
        }
    }
}

int main() {
    int arr[3] = {51, 21, 11};
    bubble_sort(arr, 3);
    printf("%d %d %d\n", arr[0], arr[1], arr[2]);
    return 0;
}

