void sort012(int a[], int n) {
    int low = 0, mid = 0, high = n - 1;
    while (mid <= high) {
        if (a[mid] == 0) {
            int t = a[low]; a[low] = a[mid]; a[mid] = t;
            low++; mid++;
        } else if (a[mid] == 1) {
            mid++;
        } else {
            int t = a[mid]; a[mid] = a[high]; a[high] = t;
            mid++; high--;
        }
    }
}

int main() {
    int a[] = {2, 0, 1};
    sort012(a, 3);
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

