#include <string.h>

void computeLPS(char *pat, int M, int *lps) {
    int len = 0, i = 1;
    lps[0] = 0;
    while (i < M) {
        if (pat[i] == pat[len]) {
            len++; lps[i] = len; i++;
        } else {
            if (len != 0) len = 0;
            else { lps[i] = 0; i++; }
        }
    }
}

int main() {
    char pat[] = "AAAA";
    int lps[4];
    computeLPS(pat, 4, lps);
    printf("%d\n", lps[3]);
    return 0;
}

