int sum_matrix(int **mat, int r, int c) {
    int total = 0;
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++)
            total += mat[i][j];
    return total;
}

int main() {
    int matrix[2][2] = {{1, 2}, {3, 4}};
    printf("%d\n", sum_matrix(matrix, 2, 2));
    return 0;
}

