int trap(int height[], int n) {
    int l = 0, r = n - 1, l_max = 0, r_max = 0, water = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            if (height[l] >= l_max) l_max = height[l];
            else water += l_max - height[l];
            l++;
        } else {
            if (height[r] >= r_max) r_max = height[r];
            else water += r_max - height[r];
            r--;
        }
    }
    return water;
}

