int count_primes(int n) {
    bool prime[11];
    for (int i = 0; i <= n; i++) prime[i] = true;
    for (int p = 2; p * p <= n; p++) {
        if (prime[p]) {
            for (int i = p * p; i <= n; i += p) prime[i] = false;
        }
    }
    int c = 0;
    for (int p = 2; p <= n; p++) if (prime[p]) c++;
    return c;
}

int main() {
    printf("%d\n", count_primes(10));
    return 0;
}

